  var HOURS_PER_YEAR = 2080;
  var LEVELS = [
    { key: 'junior', label: 'Junior', note: '25th percentile' },
    { key: 'mid',    label: 'Mid',    note: 'median' },
    { key: 'senior', label: 'Senior', note: '75th percentile' },
    { key: 'lead',   label: 'Lead',   note: '90th percentile' }
  ];
  /* The itemized hiring process. kind: time = hours x rate, team = people x hours x rate,
     amount = dollars, pct = percent of salary. rate names who the default hourly rate belongs to. */
  var LINES = [
    { key: 'hr',      label: 'Recruiter or HR time',            kind: 'time',   rate: 'hr' },
    { key: 'hrm',     label: 'HR manager time',                 kind: 'time',   rate: 'hrm' },
    { key: 'mgr',     label: 'Hiring manager time',             kind: 'time',   rate: 'mgr' },
    { key: 'iv',      label: 'Interviewers',                    kind: 'team',   rate: 'role' },
    { key: 'ads',     label: 'Job boards and ads',              kind: 'amount' },
    { key: 'agency',  label: 'Agency or recruiter fee',         kind: 'pct' },
    { key: 'checks',  label: 'Background checks and assessments', kind: 'amount' },
    { key: 'reloc',   label: 'Relocation and sign-on bonus',    kind: 'amount' },
    { key: 'onboard', label: 'Onboarding and training by colleagues', kind: 'time', rate: 'role' },
    { key: 'equip',   label: 'Equipment and software',          kind: 'amount' }
  ];
  var HR_SOC = '131071', HRM_SOC = '113121';

  /* ---------- Model (pure, tested in tools/src/employee-cost/test.js) ---------- */
  function role(key) { return D.roles.filter(function (r) { return r.key === key; })[0]; }
  function groupOf(soc) { return /^4[13]/.test(soc) ? 'so' : 'mp'; }
  function levelIndex(level) { for (var i = 0; i < LEVELS.length; i++) if (LEVELS[i].key === level) return i; return 1; }

  /* Wage for an occupation in an area. Falls back metro -> state -> US when BLS publishes no
     estimate for that cell, and says where the number came from. */
  function wage(area, soc, idx) {
    var a = D.areas[area] || D.areas.US;
    var chain = [area];
    if (a.type === 'metro' && D.areas['S' + a.state]) chain.push('S' + a.state);
    if (area !== 'US') chain.push('US');
    for (var i = 0; i < chain.length; i++) {
      var w = D.wages[chain[i]] && D.wages[chain[i]][soc];
      if (w && w[idx] != null) return { value: w[idx], from: chain[i] };
    }
    return null;
  }

  function employee(area, S, group, bonuses) {
    var r = D.groups[group], tx = D.taxes;
    var st = (D.areas[area] || D.areas.US).state;
    var su = D.suta[st] || D.suta.US;
    var sup = bonuses ? S * r.supplemental : 0;
    var pay = S + sup;
    var b = { insurance: S * r.insurance, retirement: S * r.retirement, bonuses: sup };
    var t = {
      social_security: tx.ss_rate * Math.min(pay, tx.ss_base),
      medicare: tx.medicare_rate * pay,
      futa: tx.futa_rate * Math.min(pay, tx.futa_base),
      suta: su.rate * Math.min(pay, su.base),
      workers_comp: S * r.workers_comp
    };
    var B = b.insurance + b.retirement + b.bonuses;
    var T = t.social_security + t.medicare + t.futa + t.suta + t.workers_comp;
    return { S: S, B: B, T: T, total: S + B + T, benefits: b, taxes: t };
  }

  /* Loaded hourly cost of a colleague, at the BLS median, without bonuses. */
  function hourly(area, soc) {
    var w = wage(area, soc, 1);
    if (!w) return null;
    return employee(area, w.value, groupOf(soc), false).total / HOURS_PER_YEAR;
  }

  function num(v) {
    if (v == null) return 0;
    var n = parseFloat(String(v).replace(/[^0-9.]/g, ''));
    return isNaN(n) || n < 0 ? 0 : n;
  }

  function defaultRates(area, r) {
    return { hr: hourly(area, HR_SOC), hrm: hourly(area, HRM_SOC), mgr: hourly(area, r.manager), role: hourly(area, r.soc) };
  }

  /* cfg: { role, area, level, bonuses, shrmHigh, lines: { key: { hours, people, rate, amount, pct } } } */
  function calc(cfg) {
    var r = role(cfg.role) || D.roles[0];
    var area = D.areas[cfg.area] ? cfg.area : 'US';
    var w = wage(area, r.soc, levelIndex(cfg.level));
    var e = employee(area, w.value, r.group, !!cfg.bonuses);
    var rates = defaultRates(area, r);
    var lines = cfg.lines || {}, items = {}, filled = false, sum = 0;
    LINES.forEach(function (L) {
      var v = lines[L.key] || {}, cost = 0;
      var rate = v.rate != null && String(v.rate) !== '' ? num(v.rate) : (rates[L.rate] || 0);
      if (L.kind === 'time') cost = num(v.hours) * rate;
      else if (L.kind === 'team') cost = num(v.people) * num(v.hours) * rate;
      else if (L.kind === 'pct') cost = num(v.pct) / 100 * e.S;
      else cost = num(v.amount);
      if (cost > 0) filled = true;
      items[L.key] = cost; sum += cost;
    });
    var bench = (cfg.shrmHigh ? D.hiring.average : D.hiring.median)[r.tier];
    var H = filled ? sum : bench;
    return {
      role: r, area: area, wageFrom: w.from,
      S: e.S, B: e.B, T: e.T, benefits: e.benefits, taxes: e.taxes,
      employee: e.total, hiring: H, hiringMode: filled ? 'itemized' : (cfg.shrmHigh ? 'average' : 'median'),
      hiringItems: items, rates: rates,
      total: e.total + H, after: e.total, multiple: (e.total + H) / e.S,
      timeToFill: D.hiring.time_to_fill_days[r.tier]
    };
  }

  var api = { calc: calc, wage: wage, hourly: hourly, employee: employee, data: D, lines: LINES, levels: LEVELS };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  if (typeof window === 'undefined' || typeof document === 'undefined') return;
  window.ClumaTools = window.ClumaTools || {};
  window.ClumaTools.employeeCostCalculator = api;
  if (window.__ecCalc) return; window.__ecCalc = true;

  var fmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function money(v) { return fmt.format(Math.round(v)); }
  function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }

